from pathlib import Path
import base64,json,subprocess
r=Path(__file__).resolve().parent
for n in ['source.mp4','reconstruction.mp4']:
 d=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(r/n)]));v=next(s for s in d['streams'] if s['codec_type']=='video');assert v['r_frame_rate']=='30/1';assert abs(float(d['format']['duration'])-218/30)<.05
 subprocess.run(['ffmpeg','-v','error','-i',str(r/n),'-f','null','-'],check=True)
# Remove captions/creator mark from both views to compare only the reconstructed graphic.
subprocess.run(['ffmpeg','-v','error','-y','-i',str(r/'source.mp4'),'-i',str(r/'reconstruction.mp4'),'-filter_complex',"[0:v]crop=640:324:0:0,setpts=PTS-STARTPTS[s];[1:v]scale=640:360,crop=640:324:0:0,setpts=PTS-STARTPTS[r];[s][r]hstack=inputs=2,pad=1280:360:0:36:color=0x0e151b,drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf:text='SOURCE / 8.000-15.267s':x=14:y=9:fontsize=17:fontcolor=white,drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf:text='RECONSTRUCTION / STUDY 01':x=654:y=9:fontsize=17:fontcolor=white[v]",'-map','[v]','-an','-c:v','libx264','-preset','fast','-crf','18','-movflags','+faststart',str(r/'comparison.mp4')],check=True)
def data(n):return 'data:video/mp4;base64,'+base64.b64encode((r/n).read_bytes()).decode()
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Study 01 — opening ontology map</title><style>*{box-sizing:border-box}body{margin:0;background:#0e151b;color:#e8edf2;font:16px/1.6 system-ui}main{max-width:1440px;margin:auto;padding:28px}h1{font-size:36px;line-height:1.2}p{color:#b8c7cf;max-width:1000px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.crop{aspect-ratio:640/324;overflow:hidden;background:#000}.crop video{width:100%;height:auto;display:block}h2{font-size:17px}button,select{font:inherit;padding:9px 14px;border:1px solid #54727d;background:#20343d;color:#fff;border-radius:7px;cursor:pointer}.tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}input{width:100%}.note{padding:16px;border-left:3px solid #d6a355;background:#17242c}.clock{font:14px monospace;color:#eac787}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:9px;border-bottom:1px solid #34434a}@media(max-width:700px){.grid{grid-template-columns:1fr}main{padding:15px}}</style><main><p>REELFACTORY / MOTION STUDY 01</p><h1>Opening ontology map</h1><p>Source window 00:08.000–00:15.267. The goal is to match this one graphic before adapting it to Fabric. Both views exclude the caption/logo strip so their graphic regions can be compared directly.</p><div class="grid"><section><h2>Reference</h2><div class="crop"><video id="source" playsinline muted preload="metadata" src="'''+data('source.mp4')+'''"></video></div></section><section><h2>Native SVG reconstruction</h2><div class="crop"><video id="replica" playsinline muted preload="metadata" src="'''+data('reconstruction.mp4')+'''"></video></div></section></div><div class="tools"><button id="play">Play both</button><button id="restart">Restart</button><button id="prev">−1 frame</button><button id="next">+1 frame</button><label>Speed <select id="speed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option></select></label><label><input type="checkbox" id="loop" checked style="width:auto"> Loop</label><span class="clock" id="time">0.000s</span></div><input id="scrub" type="range" min="0" max="217" step="1" value="0"><p class="note"><strong>First matching study, not a certified exact replica.</strong> The camera follows measured card bounds; timing and line growth are fitted to inspected source states. The lamp is a hand-drawn vector approximation, the font is an Arial-metric substitute, and the generic icons are Font Awesome Free. Caption animation and creator branding are separate graphics, excluded here.</p><h2>Reconstructed structure</h2><table><tr><th>Stage</th><th>Source time</th><th>Behavior</th></tr><tr><td>Central card</td><td>8.0–8.8s</td><td>Grows and fades into place; label types in</td></tr><tr><td>Inputs</td><td>10.5–12.4s</td><td>Camera fits four inputs; paths grow outward from the hub</td></tr><tr><td>Output</td><td>13.25–14.55s</td><td>Camera settles back; bidirectional link and output reveal</td></tr><tr><td>Hold</td><td>14.55–15.267s</td><td>Completed graph holds</td></tr></table><p>Editable geometry: native SVG nodes, icons, curves, text and a shared camera transform. Source video is used only in the reference player, not inside the reconstruction.</p></main><script>const a=document.querySelector('#source'),b=document.querySelector('#replica'),$=s=>document.querySelector(s);const end=218/30;let running=false;function pause(){running=false;a.pause();b.pause();$('#play').textContent='Play both'}function seek(t){pause();t=Math.max(0,Math.min(217/30,t));a.currentTime=t;b.currentTime=t;$('#scrub').value=Math.round(t*30);$('#time').textContent=t.toFixed(3)+'s / source '+(8+t).toFixed(3)+'s'}$('#play').onclick=async()=>{if(running){pause();return}if(a.currentTime>=end-.04){a.currentTime=0;b.currentTime=0}b.currentTime=a.currentTime;running=true;$('#play').textContent='Pause';await Promise.all([a.play(),b.play()])};$('#restart').onclick=()=>seek(0);$('#prev').onclick=()=>seek(a.currentTime-1/30);$('#next').onclick=()=>seek(a.currentTime+1/30);$('#scrub').oninput=e=>seek(+e.target.value/30);$('#speed').onchange=e=>{a.playbackRate=b.playbackRate=+e.target.value};function tick(){if(running){$('#scrub').value=Math.round(a.currentTime*30);$('#time').textContent=a.currentTime.toFixed(3)+'s / source '+(8+a.currentTime).toFixed(3)+'s';if(Math.abs(a.currentTime-b.currentTime)>.06)b.currentTime=a.currentTime;if(a.currentTime>=end-.04||a.ended){if($('#loop').checked){a.currentTime=0;b.currentTime=0;a.play();b.play()}else pause()}}requestAnimationFrame(tick)}tick();</script>'''
(r/'review.html').write_text(page);print('Packaged graphic-only comparison and synchronized review')
